-- Vérifie que les migrations 002 à 057 sont appliquées : une ligne par migration, « ok » = true.
-- Ne modifie rien (lecture seule). À coller dans le SQL Editor de Supabase.
-- (La 001 n'existe pas : la base de départ est supabase/schema.sql.)

with
  cols as (select table_name || '.' || column_name as c from information_schema.columns where table_schema = 'public'),
  fns as (select p.proname as name, pg_get_functiondef(p.oid) as def from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f'),
  pols as (select tablename as t, policyname as name, coalesce(qual, '') || ' ' || coalesce(with_check, '') as def from pg_policies where schemaname in ('public', 'storage')),
  trgs as (select tgname as name from pg_trigger where not tgisinternal),
  buckets as (select id from storage.buckets),
  checks (num, migration, ok) as (values
    (2,  '002 numéros et coordonnées',          exists (select 1 from cols where c = 'profiles.alumni_number') and exists (select 1 from cols where c = 'profiles.bureau_code') and exists (select 1 from fns where name = 'is_valid_phone')),
    (3,  '003 justificatif, annonces, calendrier', exists (select 1 from cols where c = 'profiles.proof_path') and exists (select 1 from cols where c = 'publications.status') and exists (select 1 from buckets where id = 'proofs')),
    (4,  '004 pages publiques',                 exists (select 1 from fns where name = 'public_overview')),
    (5,  '005 situation études / travail',      exists (select 1 from cols where c = 'profiles.situation') and exists (select 1 from cols where c = 'profiles.job_title')),
    (6,  '006 regroupement universités',        exists (select 1 from fns where name = 'place_key')),
    (7,  '007 compteur de visites',             to_regclass('public.site_counter') is not null and exists (select 1 from fns where name = 'hit_counter')),
    (8,  '008 calendrier démarches',            exists (select 1 from cols where c = 'key_dates.end_month') and exists (select 1 from cols where c = 'key_dates.url')),
    (9,  '009 questions anonymes',              to_regclass('public.questions') is not null and to_regclass('public.answers') is not null and exists (select 1 from fns where name = 'ask_question')),
    (10, '010 CV',                              exists (select 1 from cols where c = 'profiles.cv') and exists (select 1 from buckets where id = 'cvs')),
    (11, '011 générique public',                exists (select 1 from pols where t = 'app_settings' and def like '%credits%')),
    (12, '012 nationalités',                    exists (select 1 from cols where c = 'profiles.nationalities') and exists (select 1 from fns where name = 'public_overview' and def like '%nationalities%')),
    (13, '013 page Le LFK',                     exists (select 1 from pols where t = 'app_settings' and def like '%lfkStory%')),
    (14, '014 démo visible',                    exists (select 1 from pols where t = 'app_settings' and def like '%showDemo%')),
    (15, '015 inscription complète',            exists (select 1 from fns where name = 'handle_new_user')),
    (16, '016 plusieurs universités',           exists (select 1 from cols where c = 'profiles.other_schools')),
    (17, '017 universités d''échange (stats)',  exists (select 1 from fns where name = 'public_overview' and def like '%other_schools%')),
    (18, '018 pays hôtes (échange)',            exists (select 1 from fns where name = 'public_overview' and def like '%hosts%')),
    (19, '019 sexe « ne pas dire »',            exists (select 1 from pg_constraint where conname = 'profiles_gender_check' and pg_get_constraintdef(oid) like '%''N''%')),
    (20, '020 comptage sans doublons',          exists (select 1 from fns where name = 'resolve_place')),
    (21, '021 domaines, honneur, cercle',       to_regclass('public.circle_messages') is not null and exists (select 1 from cols where c = 'profiles.fields_of_study') and exists (select 1 from fns where name = 'in_circle')),
    (22, '022 droits du serveur',               has_table_privilege('service_role', 'public.profiles', 'SELECT')),
    (23, '023 rattrapage création comptes',     exists (select 1 from cols where c = 'profiles.bio') and exists (select 1 from cols where c = 'profiles.created_by_admin')),
    (24, '024 comptes créés par admin',         to_regclass('public.admin_pending_accounts') is not null),
    (25, '025 ordre du bureau',                 exists (select 1 from fns where name = 'public_overview' and def like '%bureau_code%')),
    (26, '026 classes, passage d''année',       exists (select 1 from cols where c = 'profiles.grade') and exists (select 1 from fns where name = 'promote_students') and exists (select 1 from trgs where name = 'zz_check_completion')),
    (27, '027 e-mails',                         exists (select 1 from cols where c = 'profiles.signup_notified') and exists (select 1 from buckets where id = 'mail-attachments')),
    (28, '028 proviseurs et directeurs',        exists (select 1 from pols where t = 'app_settings' and def like '%schoolLeaders%')),
    (29, '029 modifier ses publications',       exists (select 1 from pols where t = 'publications' and name = 'publications edit own')),
    (30, '030 sécurité des données',            exists (select 1 from fns where name = 'member_private_fields')),
    (31, '031 champs privés des profils',       not has_table_privilege('authenticated', 'public.profiles', 'SELECT')),
    (32, '032 noms et prénoms',                 exists (select 1 from fns where name = 'normalize_member_names') and exists (select 1 from trgs where name = 'aa_normalize_names')),
    (33, '033 clubs',                           to_regclass('public.clubs') is not null and to_regclass('public.club_members') is not null and to_regclass('public.club_posts') is not null),
    (34, '034 vérification e-mail',             exists (select 1 from cols where c = 'profiles.email_verified') and exists (select 1 from trgs where name = 'zz_sync_email_verified')),
    (35, '035 liens WhatsApp des promos',       exists (select 1 from fns where name = 'promo_whatsapp_links')),
    (36, '036 enregistrer le lien WhatsApp',    exists (select 1 from fns where name = 'set_promo_whatsapp')),
    (37, '037 partenaires masqués',             exists (select 1 from cols where c = 'institutions.hidden')),
    (38, '038 spécialité',                      exists (select 1 from cols where c = 'profiles.specialty')),
    (39, '039 messages urgents',                to_regclass('public.urgent_messages') is not null),
    (40, '040 comptes restreints',              exists (select 1 from cols where c = 'profiles.restricted') and exists (select 1 from fns where name = 'can_message') and exists (select 1 from fns where name = 'block_restricted')),
    (41, '041 restriction silencieuse',         exists (select 1 from fns where name = 'block_restricted' and def like '%Action non autorisée%')),
    (42, '042 vue messages lisibles',           to_regclass('public.messages_lisibles') is not null),
    (43, '043 messages urgents à valider',      exists (select 1 from cols where c = 'urgent_messages.resolved_at') and exists (select 1 from fns where name = 'resolve_urgent_message')),
    (44, '044 total des membres',               exists (select 1 from fns where name = 'public_overview' and def like '%''pupils''%')),
    (45, '045 publications publiques',          exists (select 1 from cols where c = 'publications.visibility') and exists (select 1 from fns where name = 'public_publications')),
    (46, '046 textes légaux',                   exists (select 1 from pols where t = 'app_settings' and def like '%legalTexts%')),
    (47, '047 textes bilingues',                exists (select 1 from cols where c = 'institutions.description_en') and exists (select 1 from fns where name = 'public_overview' and def like '%description_en%')),
    (48, '048 textes anglais',                  exists (select 1 from public.app_settings where key = 'guides' and value like '%titleEn%' and value like '%guide-it%') and exists (select 1 from public.app_settings where key = 'lfkStory' and value like '%introEn%')),
    (49, '049 stockage',                        exists (select 1 from storage.buckets where id = 'media' and file_size_limit = 10485760) and exists (select 1 from pols where t = 'objects' and name = 'media delete own or admin')),
    (50, '050 guide France : étape CAF',        exists (select 1 from public.app_settings where key = 'guides' and value like '%APL ou ALS%')),
    (51, '051 chiffres sans les MH',            exists (select 1 from fns where name = 'public_overview' and (def like '%<> ''honneur''%' or def like '%''honorary''%'))),
    (52, '052 espace des membres d''honneur',   exists (select 1 from cols where c = 'profiles.mh_access') and to_regclass('public.circle_posts') is not null and exists (select 1 from fns where name = 'in_circle' and def like '%mh_access%')),
    (53, '053 autorisation parentale',          exists (select 1 from cols where c = 'profiles.parental_path') and exists (select 1 from fns where name = 'member_private_fields' and def like '%parental_path%')),
    (54, '054 stage / alternance',              to_regclass('public.internships') is not null and exists (select 1 from fns where name = 'can_see_internships')),
    (55, '055 mots interdits',                  exists (select 1 from pols where t = 'app_settings' and def like '%bannedWords%')),
    (56, '056 guides Europe, Liban, Égypte',    exists (select 1 from public.app_settings where key = 'guides' and value like '%guide-de%' and value like '%guide-nl%')),
    (57, '057 chiffres avec les MH',            exists (select 1 from fns where name = 'public_overview' and def like '%''honorary''%'))
  )
select num, migration, ok from checks order by ok, num;
